// Des: Tests for ru-boar-acts on the sim, in Vietnamese and English: poll, note, label, quick message, friends, message requests, group admin, profile
// Flo: sim page > run each op > read page state; no force, dry, bad input, caps
// I/O: sim page > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const ba = @import("ru-boar-acts.zig"); const rig = @import("te-rigz-main.zig"); const T = std.testing;
test "poll, note, label and quick message are created through their dialogs" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); try T.expect(try ba.run(&ses, .poll, "Team A", "Lunch where?", "Pho", "Bun")); try T.expectEqualStrings("Lunch where?|Pho|Bun", try rg.js("Z.st.polls[0]")); try T.expect(try ba.run(&ses, .note, "Team A", "bring the report", "", "")); try T.expectEqualStrings("bring the report", try rg.js("Z.st.notes[0]")); try T.expect(try ba.run(&ses, .labl, "Mom", "family", "", "")); try T.expectEqualStrings("family", try rg.js("Z.st.labels[0]")); try T.expect(try ba.run(&ses, .quik, "", "hi", "Hello, how can I help?", "")); try T.expectEqualStrings("hi|Hello, how can I help?", try rg.js("Z.st.quick[0]")); try T.expect(try ba.run(&ses, .qkus, "Mom", "hi", "", "")); try T.expectEqualStrings("Hello, how can I help?", try rg.js("document.getElementById('box').innerText.trim()")); }
test "same ops work with an English interface" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); _ = try rg.js("Z.set('lang','en')"); try T.expect(try ba.run(&ses, .poll, "Team A", "Lunch?", "A", "B")); try T.expectEqualStrings("Lunch?|A|B", try rg.js("Z.st.polls[0]")); try T.expect(try ba.run(&ses, .note, "Mom", "n1", "", "")); try T.expectEqualStrings("n1", try rg.js("Z.st.notes[0]")); }
test "friend request needs force, uses the new-contact budget, and is capped" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var live = rg.ses(rig.cfgOf(), .live); try T.expectError(error.NeedForce, ba.run(&live, .freq, "", "0900000009", "", "")); var cfg = rig.cfgOf(); cfg.capz_newc_dayz = 1; var frc = rg.ses(cfg, .force); try T.expect(try ba.run(&frc, .freq, "", "0900000009", "", "")); try T.expectEqualStrings("0900000009", try rg.js("Z.st.req[0]")); frc.fake_ms += 600000; try T.expectError(error.CapHit, ba.run(&frc, .freq, "", "0900000010", "", "")); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.req.length")); }
test "accept and ignore pick the right person; message requests use the new-contact budget" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); try T.expect(try ba.run(&ses, .facc, "", "Minh", "", "")); try T.expect(try ba.run(&ses, .fign, "", "Lan", "", "")); try T.expectEqualStrings("Minh", try rg.js("Z.st.accepted[0]")); try T.expectEqualStrings("Lan", try rg.js("Z.st.ignored[0]")); try T.expect(try ba.run(&ses, .macc, "", "Zed", "", "")); try T.expectEqualStrings("Zed", try rg.js("Z.st.accepted[1]")); const sta = try rg.sto.statGet(T.allocator, rig.NOON + 1000); try T.expectEqual(@as(u32, 1), sta.newc_cnt); try T.expectError(error.NoElem, ba.run(&ses, .facc, "", "Nobody", "", "")); }
test "group admin: rename is low risk, members and leave need force" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var live = rg.ses(rig.cfgOf(), .live); try T.expect(try ba.run(&live, .gren, "Team A", "Team B", "", "")); try T.expectEqualStrings("Team A->Team B", try rg.js("Z.st.renamed[0]")); try T.expectError(error.NeedForce, ba.run(&live, .gadd, "Team A", "Lan", "", "")); try T.expectError(error.NeedForce, ba.run(&live, .glea, "Team A", "", "", "")); var frc = rg.ses(rig.cfgOf(), .force); frc.fake_ms += 600000; try T.expect(try ba.run(&frc, .gadd, "Team A", "Lan", "", "")); try T.expect(try ba.run(&frc, .grem, "Team A", "Minh", "", "")); try T.expect(try ba.run(&frc, .gdep, "Team A", "Lan", "", "")); try T.expect(try ba.run(&frc, .glea, "Team A", "", "", "")); try T.expectEqualStrings("add:Lan", try rg.js("Z.st.members[0]")); try T.expectEqualStrings("rem:Minh", try rg.js("Z.st.members[1]")); try T.expectEqualStrings("dep:Lan", try rg.js("Z.st.members[2]")); try T.expectEqualStrings("Team A", try rg.js("Z.st.leave[0]")); }
test "profile text can be read after opening the account panel" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); try T.expect(try ba.run(&ses, .prof, "", "", "", "")); const txt = try ba.profileText(&ses); try T.expect(std.mem.startsWith(u8, txt, "Họ tên: Test User")); }
test "dry run previews and changes nothing; read-only, bad input" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var dry = rg.ses(rig.cfgOf(), .dry); try T.expect(!try ba.run(&dry, .poll, "Team A", "q", "a", "b")); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.polls.length")); var rdo = rg.ses(rig.cfgOf(), .read); try T.expectError(error.BadUsage, ba.run(&rdo, .note, "Mom", "x", "", "")); var live = rg.ses(rig.cfgOf(), .live); try T.expectError(error.BadJob, ba.run(&live, .note, "Mom", "", "", "")); try T.expectError(error.BadJob, ba.run(&live, .note, "", "x", "", "")); try T.expectError(error.BadJob, ba.run(&live, .poll, "Mom", "q", "", "")); try T.expectError(error.BadJob, ba.run(&live, .quik, "", "hi", "", "")); }
